import crypto from 'node:crypto';
import { blueprintsUrl } from '../../config.js';
import getHeaders from '../../utils/get-headers.js';
const assetsUrl = blueprintsUrl('assets');
export const assetCheckUrl = `${assetsUrl}/check`;
export const assetStashUrl = `${assetsUrl}/stash`;
export async function stashAsset({ resource, prepAsset, auth, blueprintFileDir, fetchFn, installer, }) {
    let cleanup = async () => { };
    try {
        const prepResult = await prepAsset({ resource, blueprintFileDir, installer });
        if (prepResult.success === false) {
            await prepResult.cleanup();
            return {
                success: false,
                error: prepResult.error,
            };
        }
        cleanup = prepResult.cleanup;
        const b64 = prepResult.outputBuffer.toString('base64');
        const hash = hashBuffer(prepResult.outputBuffer);
        const extension = prepResult.fileExtension;
        return await stashSingleAsset({
            b64,
            hash,
            extension,
            assetParameter: prepResult.assetParameter,
            metadata: prepResult.metadata,
            cleanup,
            resourceName: resource.name,
            auth,
            fetchFn,
        });
    }
    catch (err) {
        try {
            await cleanup();
        }
        catch {
            // ignore clean up errors
        }
        return { success: false, error: err instanceof Error ? err.message : `${err}` };
    }
}
async function stashSingleAsset({ b64, hash, cleanup, resourceName, auth, fetchFn, extension, assetParameter, metadata, }) {
    try {
        try {
            const checkResponse = await fetchFn(`${assetCheckUrl}/${hash}`, {
                method: 'GET',
                headers: getHeaders(auth),
            });
            const checkJson = await checkResponse.json();
            if (checkResponse.ok && checkJson.exists && checkJson.id) {
                return { success: true, assetId: checkJson.id, assetParameter, exists: true, hash, metadata };
            }
        }
        catch { } // Continue to stash the Asset
        // Asset doesn't exist, so stash it
        const assetResponse = await fetchFn(assetStashUrl, {
            method: 'POST',
            headers: getHeaders(auth),
            body: JSON.stringify({
                file: b64,
                filename: `${resourceName}.${extension}`,
            }),
        });
        const assetJson = await assetResponse.json();
        if (assetResponse.ok) {
            return { success: true, assetId: assetJson.id, assetParameter, exists: false, hash, metadata };
        }
        return {
            success: false,
            error: `Failed to stash asset for ${resourceName}: ${assetJson.message || 'Unknown error'}`,
        };
    }
    catch (err) {
        let error = '';
        if (err instanceof Error)
            error = err.message;
        return { success: false, error };
    }
    finally {
        await cleanup();
    }
}
export function hashBuffer(buffer) {
    const hash = crypto.createHash('sha256');
    hash.update(buffer);
    return hash.digest('hex');
}
